Method.Source:
    /// <summary>
    /// MPJ_8089 - Kscerri - 04/08/2021
    /// Lookup for heirachy
    /// </summary>
    /// <param name="sender">formcontrol</param>
    /// <param name="e">args</param>
    [
        FormControlEventHandler(formControlStr(WorkflowParameters, WorkflowParameters_METHierarchyName), FormControlEventType::Lookup),
        SuppressBPWarningAttribute('BPParameterNotUsed', 'Parameter required by the event interface')
    ]
    public static void WorkflowParameters_METHierarchyName_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        Query				 query = new Query();
        QueryBuildDataSource queryBuildDataSource;
        SysTableLookup	     sysTableLookup;

        sysTableLookup = SysTableLookup::newParameters(tableNum(HcmPositionHierarchyType),sender,true);
        sysTableLookup.parmUseLookupValue(false);
        sysTableLookup.addLookupfield(fieldNum(HcmPositionHierarchyType, Name));
        sysTableLookup.addLookupfield(fieldNum(HcmPositionHierarchyType, HierarchyType));

        queryBuildDataSource = query.addDataSource(tableNum(HcmPositionHierarchyType));
        queryBuildDataSource.addSortField(fieldnum(HcmPositionHierarchyType, Name));

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();

        FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
        ce.CancelSuperCall();
    }
